const withShared = local => [...new Set([...SHARED_ASSETS, ...local])].map(asUrl);

export const IMAGE_BUNDLES = Object.freeze({
  guild: GUILD_ASSETS.map(asUrl),
  shared: SHARED_ASSETS.map(asUrl),
  goblin: withShared(GOBLIN_ASSETS),
  fungal: withShared(FUNGAL_ASSETS),
  deserter: withShared(DESERTER_ASSETS),
  withering_forest: withShared(WITHERING_FOREST_ASSETS),
  restless_ruins: withShared(RESTLESS_RUINS_ASSETS),
  // Prelisted for later use when the mine location becomes selectable.
  mines_of_decay: withShared(MINES_OF_DECAY_ASSETS),
});

export const getImageBundle = id => IMAGE_BUNDLES[id] || [];

export const getLocationImageBundleId = locationName => {
  const id = getLocationByName(locationName)?.id;
  return id && IMAGE_BUNDLES[id] ? id : 'shared';
};
